// Alvos a vigiar: cada instancia + API key hardcoded + base URL.
// SEGURANCA: keys em plain-text neste node.
const TARGETS = [
  {
    name: 'Railway',
    base: 'https://primary-production-af84.up.railway.app',
    key: 'n8n_api_7106fcbdbdf4d40033f526389678362013ef6806a543a54bc1cf025bfe8e3f7020363d15e6d31b31',
  },
  {
    name: 'Hetzner',
    base: 'https://workflows.coletiv.me',
    key: '***REDACTED***',
  },
  {
    name: 'Oracle',
    base: 'https://workflowsoracle.coletiv.me',
    key: '***REDACTED***',
  },
];
const ERROR_THRESHOLD = 8;
const WINDOW_MIN = 5;
const NEVER_KILL = [
  'heQ08w9HPkxGpNDu',
  'q2vURDwHUIi3yHB4',
  'g1IcISZKBhNQXWMt',
  'PZlO85xB0BNXaI2n',
  '7uJA7DEc0dVvyBHL',
  'wuHooOIg4Tsut0Pv',
  'URJf7Jg58IQAeXfc',
  'ApIb3XMBDSj8NHlE',
];
return TARGETS.map(t => ({
  json: {
    ...t,
    error_threshold: ERROR_THRESHOLD,
    window_min: WINDOW_MIN,
    never_kill: NEVER_KILL,
  },
}));

// Agrupa erros por workflowId dentro da janela e decide kills, por cada instancia.
// Mode: Run Once for All Items (recebe 3 responses em paralelo do HTTP node)
const cfgs = $('Config Targets').all();
const responses = $input.all();
const now = Date.now();
const out = [];

for (let i = 0; i < cfgs.length; i++) {
  const cfg = cfgs[i].json;
  const resp = (responses[i] && responses[i].json) || {};
  const base = cfg.base, key = cfg.key, instName = cfg.name;
  const THRESH = cfg.error_threshold, WINDOW_MIN = cfg.window_min, NEVER = cfg.never_kill || [];
  const windowMs = WINDOW_MIN * 60 * 1000;
  const rows = Array.isArray(resp) ? resp : (resp.data || []);
  const counts = {};
  for (const ex of rows) {
    const wfId = ex.workflowId || (ex.workflowData && ex.workflowData.id);
    if (!wfId) continue;
    const started = new Date(ex.startedAt || ex.createdAt || 0).getTime();
    if (now - started > windowMs) continue;
    counts[wfId] = counts[wfId] || { wfId, name: (ex.workflowData && ex.workflowData.name) || wfId, n: 0 };
    counts[wfId].n++;
  }
  let killed = false;
  for (const wfId of Object.keys(counts)) {
    const c = counts[wfId];
    if (c.n >= THRESH && !NEVER.includes(wfId)) {
      out.push({ json: { instance: instName, base, key, workflow_id: wfId, workflow_name: c.name, error_count: c.n, window_min: WINDOW_MIN, action: 'KILL' } });
      killed = true;
    }
  }
  if (!killed) {
    out.push({ json: { instance: instName, action: 'OK', checked: rows.length } });
  }
}
return out;

// Monta a mensagem de alerta. Preenche o teu chat_id e bot token via env.
const d = $('IF deve matar').item.json;
const text = `\u{1F6A8} KILL-SWITCH ACCIONADO\n\n` +
  `Instancia: ${d.instance}\n` +
  `Workflow: ${d.workflow_name}\n` +
  `ID: ${d.workflow_id}\n` +
  `Erros: ${d.error_count} em ${d.window_min} min\n\n` +
  `Workflow DESACTIVADO automaticamente. Investigar antes de reactivar.`;
return [{ json: { text } }];

